/* One owner thread. Upstream libdave performs all MLS and frame E2EE;
 * OpenSSL/Monocypher implement maintained AEAD. No plaintext media mode. */
#include "voice_engine.h"
#include "client_json.h"
#include "monocypher.h"
#include <dave/dave.h>
#include <opus/opus.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#define PEERS 32
#define PCM_RING 23040
struct Peer {char id[24];uint32_t ssrc;DAVEDecryptorHandle decrypt;OpusDecoder *opus;int16_t pcm[PCM_RING];unsigned read,used;uint16_t sequence;int sequence_set;unsigned key_epoch;};
struct DnxVoiceEngine {DAVESessionHandle session;DAVEEncryptorHandle encryptor;OpusEncoder *opus;char self[24],channel[24];uint32_t ssrc,nonce,timestamp;uint16_t sequence,transition;int mode,initialized,pending,active;unsigned version,epoch;unsigned char key[32];DnxVoiceSignal signal;void *user;struct Peer peers[PEERS];DnxVoiceStats stats;};
static void silent_log(DAVELoggingSeverity severity,const char *file,int line,const char *message){(void)severity;(void)file;(void)line;(void)message;}
static void mls_failure(const char *source,const char *reason,void *user){(void)source;(void)reason;DnxVoiceEngine *e=user;e->active=0;e->stats.failed=1;}
static uint32_t be32(const unsigned char *p){return (uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3];}
static void put32(unsigned char *p,uint32_t v){p[0]=(unsigned char)(v>>24);p[1]=(unsigned char)(v>>16);p[2]=(unsigned char)(v>>8);p[3]=(unsigned char)v;}
static struct Peer *peer(DnxVoiceEngine *e,const char *id,int create){struct Peer *empty=NULL;for(int i=0;i<PEERS;i++){if(!strcmp(e->peers[i].id,id))return &e->peers[i];if(!e->peers[i].id[0]&&!empty)empty=&e->peers[i];}if(!create||!empty)return NULL;snprintf(empty->id,24,"%s",id);return empty;}
static int valid_id(const char *id){size_t n=strlen(id);if(n<15||n>20)return 0;uint64_t v=0;for(size_t i=0;i<n;i++){if(id[i]<'0'||id[i]>'9'||v>(UINT64_MAX-(unsigned)(id[i]-'0'))/10)return 0;v=v*10+(unsigned)(id[i]-'0');}return 1;}
static void peer_clear(struct Peer *p){if(p->decrypt)daveDecryptorDestroy(p->decrypt);if(p->opus)opus_decoder_destroy(p->opus);crypto_wipe(p,sizeof(*p));}
static void receiver_key(DnxVoiceEngine *e,struct Peer *p){
 if(!p||!e->epoch||p->key_epoch==e->epoch)return;
 DAVEKeyRatchetHandle ratchet=daveSessionGetKeyRatchet(e->session,p->id);if(!ratchet)return;
 if(!p->decrypt)p->decrypt=daveDecryptorCreate();
 if(p->decrypt){daveDecryptorTransitionToPassthroughMode(p->decrypt,false);daveDecryptorTransitionToKeyRatchet(p->decrypt,ratchet);p->key_epoch=e->epoch;}
 daveKeyRatchetDestroy(ratchet);
}
static int recognize(DnxVoiceEngine *e,const char *id){
 if(!valid_id(id))return 0;
 daveSessionAddRecognizedUser(e->session,id);if(!strcmp(e->self,id))return 1;
 struct Peer *p=peer(e,id,1);if(!p)return 0;receiver_key(e,p);return 1;
}
static int emit(DnxVoiceEngine *e,int binary,const unsigned char *data,size_t n){if(n>262144||!e->signal||!e->signal(e->user,binary,data,n)){e->stats.failed=1;return 0;}return 1;}
static int send_binary(DnxVoiceEngine *e,unsigned op,const unsigned char *p,size_t n){if(n>262143)return 0;unsigned char *message=malloc(n+1);if(!message)return 0;message[0]=(unsigned char)op;memcpy(message+1,p,n);int ok=emit(e,1,message,n+1);crypto_wipe(message,n+1);free(message);return ok;}
static int transition_json(DnxVoiceEngine *e,int op,unsigned transition){char json[96];int n=snprintf(json,sizeof(json),"{\"op\":%d,\"d\":{\"transition_id\":%u}}",op,transition);return emit(e,0,(unsigned char*)json,(size_t)n);}
static int package(DnxVoiceEngine *e){uint8_t *bytes=NULL;size_t n=0;daveSessionGetMarshalledKeyPackage(e->session,&bytes,&n);int ok=bytes&&n&&send_binary(e,26,bytes,n);if(bytes){crypto_wipe(bytes,n);daveFree(bytes);}if(ok)e->stats.key_packages++;return ok;}
static void receiver_keys(DnxVoiceEngine *e){e->epoch++;for(int i=0;i<PEERS;i++)if(e->peers[i].id[0])receiver_key(e,&e->peers[i]);}
static int execute(DnxVoiceEngine *e,unsigned transition){if(!e->pending||e->transition!=transition)return 0;DAVEKeyRatchetHandle ratchet=daveSessionGetKeyRatchet(e->session,e->self);e->pending=0;if(!ratchet){e->active=0;return 1;}daveEncryptorSetKeyRatchet(e->encryptor,ratchet);daveKeyRatchetDestroy(ratchet);daveEncryptorSetPassthroughMode(e->encryptor,false);e->active=1;e->stats.mls_updates++;return 1;}
unsigned dnx_voice_max_version(void){return daveMaxSupportedProtocolVersion();}
DnxVoiceEngine *dnx_voice_create(const char *self,const char *channel,DnxVoiceSignal signal,void *user){if(!self||!channel||!valid_id(self)||!valid_id(channel))return NULL;daveSetLogSinkCallback(silent_log);DnxVoiceEngine *e=calloc(1,sizeof(*e));if(!e)return NULL;snprintf(e->self,24,"%s",self);snprintf(e->channel,24,"%s",channel);e->signal=signal;e->user=user;e->session=daveSessionCreate(NULL,NULL,mls_failure,e);e->encryptor=daveEncryptorCreate();int error;e->opus=opus_encoder_create(48000,2,OPUS_APPLICATION_VOIP,&error);if(!e->session||!e->encryptor||!e->opus||RAND_bytes((unsigned char*)&e->sequence,sizeof(e->sequence))!=1||RAND_bytes((unsigned char*)&e->timestamp,sizeof(e->timestamp))!=1){dnx_voice_destroy(e);return NULL;}opus_encoder_ctl(e->opus,OPUS_SET_BITRATE(64000));opus_encoder_ctl(e->opus,OPUS_SET_INBAND_FEC(1));opus_encoder_ctl(e->opus,OPUS_SET_PACKET_LOSS_PERC(10));daveEncryptorSetPassthroughMode(e->encryptor,false);return e;}
void dnx_voice_destroy(DnxVoiceEngine *e){if(!e)return;for(int i=0;i<PEERS;i++)peer_clear(&e->peers[i]);if(e->session)daveSessionDestroy(e->session);if(e->encryptor)daveEncryptorDestroy(e->encryptor);if(e->opus)opus_encoder_destroy(e->opus);crypto_wipe(e,sizeof(*e));free(e);}
void dnx_voice_ssrc(DnxVoiceEngine *e,uint32_t ssrc){e->ssrc=ssrc;daveEncryptorAssignSsrcToCodec(e->encryptor,ssrc,DAVE_CODEC_OPUS);}
int dnx_voice_signal_json(DnxVoiceEngine *e,const char *json){DnxJson root=dj_root(json),d=dj_field(root,"d");int op=dj_int(root,"op",-1);
 if(op==11){DnxJson id;const char *p=NULL;while(dj_next(dj_field(d,"user_ids"),&p,&id)){char value[24];if(!dj_string(id,value,24)||!recognize(e,value))return -1;}return 1;}
 if(op==13){char id[24];if(dj_get(d,"user_id",id,24)&&valid_id(id)){daveSessionRemoveRecognizedUser(e->session,id);struct Peer *p=peer(e,id,0);if(p)peer_clear(p);}return 1;}
 if(op==5){char id[24];if(!dj_get(d,"user_id",id,24)||!valid_id(id))return -1;/* Opcode5 is authenticated Voice Gateway identity/SSRC signaling, never raw RTP. */if(!recognize(e,id))return -1;struct Peer *p=peer(e,id,0);if(p){DnxJson value=dj_field(d,"ssrc");char *end;unsigned long long s=value.p?strtoull(value.p,&end,10):0;if(!value.p||end!=value.end||!s||s>UINT32_MAX)return -1;if(p->ssrc!=(uint32_t)s){p->ssrc=(uint32_t)s;p->sequence_set=0;p->read=p->used=0;crypto_wipe(p->pcm,sizeof(p->pcm));if(p->opus)opus_decoder_ctl(p->opus,OPUS_RESET_STATE);}}return 1;}
 if(op==4){if(e->stats.transport_ready)return -1;char mode[80];dj_get(d,"mode",mode,sizeof(mode));e->mode=!strcmp(mode,"aead_aes256_gcm_rtpsize")?1:!strcmp(mode,"aead_xchacha20_poly1305_rtpsize")?2:0;if(!e->mode)return -1;DnxJson byte;const char *p=NULL;int n=0;while(dj_next(dj_field(d,"secret_key"),&p,&byte)){if(n>=32)return -1;char *end;long b=strtol(byte.p,&end,10);if(end!=byte.end||b<0||b>255)return -1;e->key[n++]=(unsigned char)b;}if(n!=32)return -1;e->version=(unsigned)dj_int(d,"dave_protocol_version",0);if(!e->version||e->version>dnx_voice_max_version())return -1;e->stats.transport_ready=1;e->initialized=1;daveSessionInit(e->session,(uint16_t)e->version,strtoull(e->channel,NULL,10),e->self);return package(e)?1:-1;}
 if(op==24){int version=dj_int(d,"protocol_version",0);if(version<1||(unsigned)version>dnx_voice_max_version())return -1;e->active=0;e->version=(unsigned)version;if(dj_int(d,"epoch",0)==1){daveSessionInit(e->session,(uint16_t)version,strtoull(e->channel,NULL,10),e->self);e->initialized=1;return package(e)?1:-1;}daveSessionSetProtocolVersion(e->session,(uint16_t)version);return 1;}
 if(op==21){int version=dj_int(d,"protocol_version",0),t=dj_int(d,"transition_id",-1);if(!version||(unsigned)version>dnx_voice_max_version()||t<0||t>65535)return -1;e->pending=1;e->transition=(uint16_t)t;if(!t)return execute(e,0);return transition_json(e,23,(unsigned)t)?1:-1;}
 if(op==22){e->stats.executes++;int t=dj_int(d,"transition_id",-1);return t>=0&&t<=65535&&execute(e,(unsigned)t)?1:-1;}return 0;
}
int dnx_voice_signal_binary(DnxVoiceEngine *e,const unsigned char *data,size_t n){if(n<3||n>262144)return -1;unsigned op=data[2];const unsigned char *p=data+3;n-=3;
 if(op==25){e->stats.external_senders++;daveSessionSetExternalSender(e->session,p,n);return e->stats.failed?-1:1;}
 if(op==27){e->stats.proposals++;uint8_t *out=NULL;size_t size=0;daveSessionProcessProposals(e->session,p,n,&out,&size);int ok=1;if(size)ok=send_binary(e,28,out,size);if(out){crypto_wipe(out,size);daveFree(out);}return ok?1:-1;}
 if(op==29||op==30){if(op==29)e->stats.commits++;else e->stats.welcomes++;if(n<3||!e->initialized)return -1;unsigned t=(unsigned)p[0]<<8|p[1];int ok=0,ignored=0;
  if(op==29){DAVECommitResultHandle result=daveSessionProcessCommit(e->session,p+2,n-2);if(result){ok=!daveCommitResultIsFailed(result);ignored=daveCommitResultIsIgnored(result);daveCommitResultDestroy(result);}}
  else {DAVEWelcomeResultHandle result=daveSessionProcessWelcome(e->session,p+2,n-2);ok=result!=NULL;if(result)daveWelcomeResultDestroy(result);}
  if(ignored)return 1;
  if(!ok){e->active=0;transition_json(e,31,t);daveSessionInit(e->session,(uint16_t)e->version,strtoull(e->channel,NULL,10),e->self);return package(e)?1:-1;}
  receiver_keys(e);e->pending=1;e->transition=(uint16_t)t;if(!t)return execute(e,0);return transition_json(e,23,t)?1:-1;
 }return 0;
}
static int aes_gcm(int encrypt,const unsigned char key[32],const unsigned char nonce[12],const unsigned char *ad,int ad_size,const unsigned char *in,int size,unsigned char *out,unsigned char tag[16]){EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();if(!ctx)return 0;int n=0,total=0,ok=EVP_CipherInit_ex(ctx,EVP_aes_256_gcm(),NULL,NULL,NULL,encrypt)==1&&EVP_CIPHER_CTX_ctrl(ctx,EVP_CTRL_GCM_SET_IVLEN,12,NULL)==1&&EVP_CipherInit_ex(ctx,NULL,NULL,key,nonce,encrypt)==1&&EVP_CipherUpdate(ctx,NULL,&n,ad,ad_size)==1;if(ok){ok=EVP_CipherUpdate(ctx,out,&n,in,size)==1;total=n;}if(!encrypt&&ok)ok=EVP_CIPHER_CTX_ctrl(ctx,EVP_CTRL_GCM_SET_TAG,16,tag)==1;if(ok)ok=EVP_CipherFinal_ex(ctx,out+total,&n)==1;if(encrypt&&ok)ok=EVP_CIPHER_CTX_ctrl(ctx,EVP_CTRL_GCM_GET_TAG,16,tag)==1;EVP_CIPHER_CTX_free(ctx);return ok;}
int dnx_voice_encode(DnxVoiceEngine *e,const int16_t pcm[960],unsigned char packet[2048]){if(!e->active||!e->stats.transport_ready||e->stats.failed||!e->ssrc)return 0;if(e->nonce==UINT32_MAX){e->stats.failed=1;return 0;}unsigned char opus[1500],encrypted[1800];int16_t stereo[1920];for(int i=0;i<960;i++)stereo[i*2]=stereo[i*2+1]=pcm[i];int n=opus_encode(e->opus,stereo,960,opus,sizeof(opus));crypto_wipe(stereo,sizeof(stereo));size_t bytes=0;if(n<1||daveEncryptorEncrypt(e->encryptor,DAVE_MEDIA_TYPE_AUDIO,e->ssrc,opus,(size_t)n,encrypted,sizeof(encrypted),&bytes)!=DAVE_ENCRYPTOR_RESULT_CODE_SUCCESS||bytes>1800){crypto_wipe(opus,sizeof(opus));e->stats.encode_errors++;return 0;}packet[0]=0x80;packet[1]=0x78;packet[2]=(unsigned char)(e->sequence>>8);packet[3]=(unsigned char)e->sequence;put32(packet+4,e->timestamp);put32(packet+8,e->ssrc);unsigned char nonce[24]={0},tag[16];put32(nonce,++e->nonce);int ok=1;if(e->mode==2)crypto_aead_lock(packet+12,tag,e->key,nonce,packet,12,encrypted,bytes);else ok=aes_gcm(1,e->key,nonce,packet,12,encrypted,(int)bytes,packet+12,tag);if(ok){memcpy(packet+12+bytes,tag,16);memcpy(packet+28+bytes,nonce,4);e->sequence++;e->timestamp+=960;e->stats.tx++;}crypto_wipe(opus,sizeof(opus));crypto_wipe(encrypted,sizeof(encrypted));return ok?(int)(bytes+32):0;}
int dnx_voice_receive(DnxVoiceEngine *e,const unsigned char *packet,size_t n){e->stats.udp_received++;if(!e->stats.transport_ready||n<32||n>2048||(packet[0]>>6)!=2||(packet[1]&127)!=120)return 0;size_t header=12+(packet[0]&15)*4u;if(packet[0]&16)header+=4;if(header+20>n)return 0;uint32_t ssrc=be32(packet+8);struct Peer *p=NULL;for(int i=0;i<PEERS;i++)if(e->peers[i].id[0]&&e->peers[i].ssrc==ssrc){p=&e->peers[i];break;}if(!p){e->stats.unknown_ssrc++;return 0;}if(!p->decrypt){e->stats.no_key++;return 0;}unsigned char nonce[24]={0},plain[2048],opus[1500],tag[16];memcpy(nonce,packet+n-4,4);size_t size=n-header-20;memcpy(tag,packet+n-20,16);int ok=e->mode==2?crypto_aead_unlock(plain,tag,e->key,nonce,packet,header,packet+header,size)==0:aes_gcm(0,e->key,nonce,packet,(int)header,packet+header,(int)size,plain,tag);if(!ok){e->stats.dropped++;e->stats.transport_rejected++;return 0;}size_t skip=0;if(packet[0]&16){skip=((size_t)packet[header-2]<<8|packet[header-1])*4;if(skip>size)return 0;}if(packet[0]&32){if(!size||!plain[size-1]||plain[size-1]>size-skip)return 0;size-=plain[size-1];}size_t bytes=0;if(daveDecryptorDecrypt(p->decrypt,DAVE_MEDIA_TYPE_AUDIO,plain+skip,size-skip,opus,sizeof(opus),&bytes)!=DAVE_DECRYPTOR_RESULT_CODE_SUCCESS){crypto_wipe(plain,sizeof(plain));crypto_wipe(opus,sizeof(opus));e->stats.dropped++;e->stats.e2ee_rejected++;return 0;}uint16_t sequence=(uint16_t)((unsigned)packet[2]<<8|packet[3]);if(p->sequence_set&&(int16_t)(sequence-p->sequence)<=0){e->stats.dropped++;return 0;}p->sequence_set=1;p->sequence=sequence;int error;if(!p->opus)p->opus=opus_decoder_create(48000,2,&error);int16_t decoded[11520];int frames=p->opus?opus_decode(p->opus,opus,(opus_int32)bytes,decoded,5760,0):-1;crypto_wipe(plain,sizeof(plain));crypto_wipe(opus,sizeof(opus));if(frames<1){e->stats.dropped++;e->stats.opus_rejected++;return 0;}unsigned samples=(unsigned)frames*2;if(p->used+samples>PCM_RING){unsigned remove=p->used+samples-PCM_RING;p->read=(p->read+remove)%PCM_RING;p->used-=remove;}for(unsigned i=0;i<samples;i++)p->pcm[(p->read+p->used+i)%PCM_RING]=decoded[i];p->used+=samples;crypto_wipe(decoded,sizeof(decoded));e->stats.rx++;return 1;}
void dnx_voice_mix(DnxVoiceEngine *e,int16_t stereo[1920]){int32_t mix[1920]={0};for(int i=0;i<PEERS;i++){struct Peer *p=&e->peers[i];unsigned n=p->used<1920?p->used:1920;for(unsigned j=0;j<n;j++)mix[j]+=p->pcm[(p->read+j)%PCM_RING];p->read=(p->read+n)%PCM_RING;p->used-=n;}for(int i=0;i<1920;i++)stereo[i]=(int16_t)(mix[i]>32767?32767:mix[i]<-32768?-32768:mix[i]);}
void dnx_voice_stats(const DnxVoiceEngine *e,DnxVoiceStats *stats){*stats=e->stats;stats->secure_ready=e->active;stats->peer_count=stats->ssrc_count=0;for(int i=0;i<PEERS;i++)if(e->peers[i].id[0]){stats->peer_count++;if(e->peers[i].ssrc)stats->ssrc_count++;}}
